// Solve a 1D cable of ToR-ORd cells on an NVIDIA GPU, with the kernels generated by
//
//   gotranx ode2cuda ToRORd_dyn_chloride.ode --scheme generalized_rush_larsen --namespace tor_ord -o tor_ord.cuh
//
// One GPU thread per cell. Each time step first advances every cell's ODE with the generated
// scheme, then lets the potential diffuse to the neighbouring cells (cable.cuh). Every
// millisecond the potential of every cell is written as one row of a CSV file.
//
// Build and run: nvcc -std=c++17 -O3 -arch=sm_80 main.cu -o cable && ./cable v.csv
#include <cstdio>
#include <cstdlib>
#include <vector>

#include "cable.cuh"
#include "tor_ord.cuh"

static void check(cudaError_t error, const char *call, int line)
{
    if (error != cudaSuccess) {
        std::fprintf(stderr, "%s failed (line %d): %s\n", call, line, cudaGetErrorString(error));
        std::exit(1);
    }
}
#define CHECK(call) check((call), #call, __LINE__)

static int lookup(int index, const char *name)
{
    if (index < 0) {
        std::fprintf(stderr, "No variable named '%s' in the model\n", name);
        std::exit(1);
    }
    return index;
}

int main(int argc, char *argv[])
{
    const char *output = argc > 1 ? argv[1] : "v.csv";
    const std::int64_t n_cells = 500;  // a 50 mm cable
    const double t_end = 500.0;        // ms
    const int threads = 128;
    const int blocks = static_cast<int>((n_cells + threads - 1) / threads);

    // The parameters are shared by all cells. The model's own stimulus would stimulate every
    // cell at once, so switch it off: the cable is stimulated at one end instead (cable.cuh)
    std::vector<double> parameters(tor_ord::NUM_PARAMS);
    tor_ord::init_parameter_values(parameters.data());
    parameters[lookup(tor_ord::parameter_index("i_Stim_Amplitude"), "i_Stim_Amplitude")] = 0.0;
    const int v = lookup(tor_ord::state_index("v"), "v");

    // The states of all cells, state-major: state i of cell c is states[i * n_cells + c], so
    // the potential of all cells is the contiguous row states + v * n_cells
    double *states, *d_parameters, *v_new;
    CHECK(cudaMalloc(&states, sizeof(double) * tor_ord::NUM_STATES * n_cells));
    CHECK(cudaMalloc(&d_parameters, sizeof(double) * tor_ord::NUM_PARAMS));
    CHECK(cudaMalloc(&v_new, sizeof(double) * n_cells));
    CHECK(cudaMemcpy(d_parameters, parameters.data(), sizeof(double) * tor_ord::NUM_PARAMS,
                     cudaMemcpyHostToDevice));
    tor_ord::init_state_values<<<blocks, threads>>>(states, n_cells);
    CHECK(cudaGetLastError());

    std::FILE *out = std::fopen(output, "w");
    if (out == nullptr) {
        std::fprintf(stderr, "Could not open %s\n", output);
        return 1;
    }
    std::vector<double> v_host(n_cells);
    double *potential = states + v * n_cells;

    const int num_steps = static_cast<int>(t_end / cable::dt);
    const int save_every = static_cast<int>(1.0 / cable::dt);  // every ms
    for (int step = 0; step <= num_steps; step++) {
        const double t = step * cable::dt;
        if (step % save_every == 0) {
            CHECK(cudaMemcpy(v_host.data(), potential, sizeof(double) * n_cells,
                             cudaMemcpyDeviceToHost));
            std::fprintf(out, "%g", t);
            for (std::int64_t c = 0; c < n_cells; c++) std::fprintf(out, ",%.6g", v_host[c]);
            std::fprintf(out, "\n");
        }
        // The cell model, in place: the scheme reads and writes the same states
        tor_ord::generalized_rush_larsen<<<blocks, threads>>>(states, t, cable::dt, d_parameters,
                                                             states, n_cells);
        // The diffusion of the potential, and the stimulus at the start of the cable
        cable::diffuse<<<blocks, threads>>>(potential, v_new, n_cells, cable::stimulus(t));
        CHECK(cudaMemcpy(potential, v_new, sizeof(double) * n_cells, cudaMemcpyDeviceToDevice));
    }
    CHECK(cudaGetLastError());
    CHECK(cudaDeviceSynchronize());

    std::fclose(out);
    CHECK(cudaFree(states));
    CHECK(cudaFree(d_parameters));
    CHECK(cudaFree(v_new));
    return 0;
}
